{
  "correction_rules": [
    "Adjust forecasts downward if sentiment is neutral or negative (0.00) and model shows persistent overestimation.",
    "Reduce forecast peaks by 5-10% after a spike, especially if sentiment remains flat or negative.",
    "Apply mean reversion bias: if 30-day forecast is > 10% above recent 18-day average, reduce by 10-15%.",
    "If sentiment history includes a single positive signal (0.25), slightly increase forecast but cap at 10% above prior peak.",
    "Avoid long-term overconfidence: if model forecast exceeds true outcome by > 15% for 3 consecutive days, apply downward correction.",
    "For horizon > 14 days, reduce forecast by 2-5% per additional day if sentiment remains unchanged or negative."
  ]
}
